	@Test
	void aFailureAfterTheResponseIsCommittedIsNotDisguisedAsAnotherAnswer() throws Exception {
		servlet();
		TupleQueryResult result = failingTuples(5_000, new QueryInterruptedException("late timeout"));
		when(tupleQuery.evaluate()).thenReturn(result);
		MockHttpServletResponse response = new MockHttpServletResponse();

		assertThatThrownBy(() -> servlet.service(post(SELECT), response))
				.isInstanceOf(QueryInterruptedException.class)
				.hasMessage("late timeout");

		assertThat(response.isCommitted()).isTrue();
		assertThat(response.getStatus()).isEqualTo(200);
		assertThat(response.getContentAsString()).startsWith("{");
	}

	@Test
	void aTimeoutAfterTheFirstRowsButBeforeTheResponseIsCommittedStillAnswersRequestTimeout() throws Exception {
		servlet();
		TupleQueryResult result = failingTuples(3, new QueryInterruptedException("timed out after three rows"));
		when(tupleQuery.evaluate()).thenReturn(result);
		// Like Tomcat and Jetty: once the output stream is in use, getWriter() is refused, even after resetBuffer().
		MockHttpServletResponse response = new MockHttpServletResponse() {
			private boolean streamed;

			@Override
			public ServletOutputStream getOutputStream() {
				streamed = true;
				return super.getOutputStream();
			}

			@Override
			public PrintWriter getWriter() throws UnsupportedEncodingException {
				if (streamed) {
					throw new IllegalStateException("getOutputStream() has already been called for this response");
				}
				return super.getWriter();
			}
		};

		servlet.service(post(SELECT), response);

		assertThat(response.getStatus()).isEqualTo(408);
		assertThat(response.getContentType()).startsWith("text/plain");
		assertThat(response.getContentAsString()).isEqualTo("timed out after three rows");
		verify(result).close();
	}

	@Test
	void emptyResultsAreCompleteDocuments() throws Exception {
		servlet();
		GraphQueryResult empty = failingStatements(0, null);
		when(graphQuery.evaluate()).thenReturn(empty);

		for (String query : List.of(SELECT, CONSTRUCT)) {
			MockHttpServletResponse response = run(post(query));

			assertThat(response.getStatus()).as(query).isEqualTo(200);
			JsonNode json = JSON.readTree(response.getContentAsString());
			assertThat(json.path("head").path("vars")).extracting(JsonNode::asText).containsExactlyElementsOf(NAMES);
			assertThat(json.path("results").path("bindings")).as(query).isEmpty();
		}
	}

	@Test
	void rowsBeforeTheLimitStillStreamAfterTheFirstRowIsReadAhead() throws Exception {
		servlet();
		TupleQueryResult result = failingTuples(3, null);
		when(tupleQuery.evaluate()).thenReturn(result);
		MockHttpServletRequest request = post(SELECT);
		request.setParameter("row-limit", "2");

		MockHttpServletResponse response = run(request);

		assertThat(JSON.readTree(response.getContentAsString()).path("results").path("bindings")).hasSize(2);
	}

	@Test
	void theResponseSaysWhetherTheRowLimitCutTheResult() throws Exception {
		servlet();
		for (int rows : new int[] { 2, 3 }) {
			TupleQueryResult tuples = failingTuples(rows, null);
			GraphQueryResult statements = failingStatements(rows, null);
			when(tupleQuery.evaluate()).thenReturn(tuples);
			when(graphQuery.evaluate()).thenReturn(statements);
			for (String query : List.of(SELECT, CONSTRUCT)) {
				MockHttpServletRequest request = post(query);
				request.setParameter("row-limit", "2");

				JsonNode json = JSON.readTree(run(request).getContentAsString());

				assertThat(json.path("results").path("bindings")).hasSize(2);
				assertThat(json.path("rdf4j:truncated").isBoolean()).as("%s of %d rows", query, rows).isTrue();
				assertThat(json.path("rdf4j:truncated").asBoolean()).as("%s of %d rows", query, rows)
						.isEqualTo(rows > 2);
			}
		}
	}

	private MockHttpServletResponse run(MockHttpServletRequest request) throws Exception {
		MockHttpServletResponse response = new MockHttpServletResponse();
		servlet.service(request, response);
		return response;
	}

	private static MockHttpServletRequest post(String query) {
		MockHttpServletRequest request = new MockHttpServletRequest("POST", "/graph");
		request.setContentType("application/sparql-query; charset=utf-8");
		request.setContent(query.getBytes(StandardCharsets.UTF_8));
		request.addHeader("Accept", "application/sparql-results+json");
		return request;
	}

	/** {@code rows} solutions, then the failure (or the end, when it is null). */
	private static TupleQueryResult failingTuples(int rows, RuntimeException failure) {
		TupleQueryResult result = mock(TupleQueryResult.class);
		AtomicInteger served = new AtomicInteger();
		when(result.getBindingNames()).thenReturn(NAMES);
		when(result.hasNext()).thenAnswer(ignored -> {
			if (served.get() < rows) {
				return true;
			}
			if (failure != null) {
				throw failure;
			}
			return false;
		});
		when(result.next()).thenAnswer(ignored -> {
			int index = served.getAndIncrement();
			return (BindingSet) new ListBindingSet(NAMES, VF.createIRI("urn:source:" + index),
					VF.createIRI("urn:predicate"), VF.createIRI("urn:target:" + index));
		});
		return result;
	}

	private static GraphQueryResult failingStatements(int statements, RuntimeException failure) {
		GraphQueryResult result = mock(GraphQueryResult.class);
		AtomicInteger served = new AtomicInteger();
		when(result.hasNext()).thenAnswer(ignored -> {
			if (served.get() < statements) {
				return true;
			}
			if (failure != null) {
				throw failure;
			}
			return false;
		});
		when(result.next()).thenAnswer(ignored -> {
			int index = served.getAndIncrement();
			return (Statement) VF.createStatement(VF.createIRI("urn:s:" + index), VF.createIRI("urn:p"),
					VF.createIRI("urn:o"));
		});
		return result;
	}
